  "dt": "శివుని కుమారుడు; ఆరుగురు కృత్తికలు పాలిచ్చి పెంచినందుకు ఆరు ముఖాలు కలవాడు. దేవసేనాపతి అయ్యాడు. స్కందుడు, సుబ్రహ్మణ్యుడు, మురుగన్ అని కూడా అంటారు."
