    "Suddenly — *twang!* — a niṣāda, a hunter hidden in the bushes, shot an arrow and killed the male bird right before Vālmīki's eyes. It fell to the ground, bleeding and struggling. Seeing him, his partner cried out pitifully, again and again.",
    "అకస్మాత్తుగా — *ఝుమ్!* — పొదల్లో దాక్కున్న ఒక నిషాదుడు, అంటే వేటగాడు, వాల్మీకి చూస్తుండగానే బాణం వేసి మగ పక్షిని చంపాడు. అది రక్తంతో గిలగిలా కొట్టుకుంటూ నేలపై పడింది. దాన్ని చూసి దాని జత పక్షి దీనంగా మళ్ళీ మళ్ళీ అరిచింది."
