    "p",
    "A moment later Vālmīki was troubled. \"What have I said, in my sorrow for this bird?\" he wondered. Then he noticed something strange: the words had come out perfectly measured — four quarters of eight syllables each, which could be sung to the music of the vīṇā.",
    "మరుక్షణమే వాల్మీకి కలవరపడ్డారు. \"ఈ పక్షి కోసం దుఃఖంలో నేను ఏమి అన్నాను?\" అనుకున్నారు. అప్పుడు ఒక విచిత్రం గమనించారు: ఆ మాటలు సరిగ్గా కొలిచినట్లు వచ్చాయి — ఎనిమిదేసి అక్షరాలున్న నాలుగు పాదాలు, వీణపై పాడుకోగలిగేలా."
