    "p",
    "Brahmā smiled. \"Do not worry, Vālmīki. This verse came to you by my will. Now, best of sages, tell the whole story of Rāma, just as you heard it from Nārada — in this same kind of verse. Whatever is known and whatever is hidden about Rāma, Lakṣmaṇa, Sītā and the rākṣasas will all become clear to you. Not one word you write will be untrue.\"",
    "బ్రహ్మ చిరునవ్వు నవ్వారు. \"వాల్మీకీ, చింతించకు. ఈ శ్లోకం నా సంకల్పంతోనే నీకు వచ్చింది. మునిశ్రేష్ఠా, నారదుడి నుండి విన్నట్లే రాముని కథను మొత్తం ఇలాంటి శ్లోకాలలోనే చెప్పు. రాముడు, లక్ష్మణుడు, సీత, రాక్షసుల గురించి తెలిసినదీ, దాగి ఉన్నదీ — అంతా నీకు స్పష్టమవుతుంది. నువ్వు రాసే ఒక్క మాట కూడా అసత్యం కాదు.\""
